    "privacy.cookieless.text": "Este sitio web no utiliza cookies de rastreo publicitario ni almacenamiento invasivo de IP, prescindiendo de banners publicitarios y protegiendo la privacidad del usuario.",

    // === SEO / METADATA ===
    "seo.home.title": "Luis M. Almeida | Perito Tasador de Arte y Patrimonio",
    "seo.home.desc": "Especialista en tasación pericial de obras de arte, peritaje judicial, herencias y protección del patrimonio cultural. 40+ años.",
    "seo.n1.title": "Peritaje y Tasación para Coleccionistas de Arte | Almeida",
