    // === PERFIL (perfil.html) ===
    "perfil.breadcrumb": "My Profile",
    "perfil.hero.h1": "Luis Manuel Almeida Luis — Fine Art & Heritage Appraiser",
    "perfil.hero.subtitle": "40+ years of institutional career. Over 20,000 artworks and heritage assets inventoried and appraised. Specialist in technical expertise, cataloguing, estate partition, judicial appraisal, and cultural heritage protection.",
    "perfil.problem.label": "The Problem",
    "perfil.problem.text": "The art market operates with information asymmetries that expose collectors, heirs, and institutions to forgeries, overvaluation, and litigation. Without independent, technical expertise free from conflict of interest, the true value of an asset remains uncertain.",
    "perfil.value.text": "Luis Manuel Almeida Luis conducts appraisal under strict zero-conflict-of-interest standards: he neither buys, sells, nor charges percentage-based fees on appraised value. Each report is an autonomous and methodologically robust technical opinion, backed by 41 years as an airport customs and border protection specialist (1988–2024) and 19 years heading the Department of Registry and Inventory at the National Registry of Cultural Property of the Republic of Cuba.",
    "perfil.areas.title": "Areas of Expertise",
    "perfil.area.1.title": "Fine Art Appraisal & Technical Expertise",
    "perfil.area.1.desc": "Stylistic, material, bibliographic, and provenance analysis. Appraisal reports, technical cataloguing records, objective economic valuations, and condition diagnostics.",
    "perfil.area.2.title": "Judicial Appraisal, Partition & Customs",
    "perfil.area.2.desc": "Partition Appraiser in 15+ estate liquidations. Technical reports with procedural validity and judicial assistance. 41 years in airport customs and border protection (landmark cases: Diego Velázquez, Demétre Chiparus).",
    "perfil.area.3.title": "Cultural Heritage & Illicit Trafficking",
    "perfil.area.3.desc": "Official inventory campaigns of Cuban cultural heritage assets across embassies in 15+ countries. Illicit trafficking prevention (Carabinieri TPC, IBERMUSEOS, UNESCO). Submerged heritage cataloguing (Palemón, Mercedes wrecks).",
    "perfil.area.4.title": "Teaching, Methodology & International Cooperation",
    "perfil.area.4.desc": "25+ years uninterrupted university teaching as Adjunct Associate Professor (ISA, UH, San Gerónimo). Co-author of Dr. Rosenberg's textbook (Ludwig Foundation/CNPC). UNESCO publications. Cusco Forum (OEI/UNESCO). Distinction for Cuban Culture.",
    "perfil.evidence.title": "Career Evidence & Milestones",
    "perfil.evidence.1": "1984 — Detection at airport customs and restitution of an artwork attributed to Diego Velázquez to the National Museum of Fine Arts (joint technical opinion with Dr. Marta Arjona Pérez, CNPC President).",
